import sqlite3
import secrets
from datetime import datetime
from typing import Optional

from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from pydantic import BaseModel, EmailStr, field_validator
from passlib.context import CryptContext
from jose import JWTError, jwt
from starlette.responses import Response
import uvicorn

# Configuration
SECRET_KEY = "super-secret-key-change-in-production"
ALGORITHM = "HS256"
DATABASE = "db.sqlite3"

# Password hashing
pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")

# JWT helpers
def create_token(user_id: int) -> str:
    payload = {"sub": str(user_id)}
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)

def decode_token(token: str) -> int:
    payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    return int(payload["sub"])

# Database initialization
def init_db():
    conn = sqlite3.connect(DATABASE)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            hashed_password TEXT NOT NULL,
            profile_id TEXT UNIQUE NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS submissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            rounded_lat REAL NOT NULL,
            rounded_lon REAL NOT NULL,
            timestamp TEXT NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users(id)
        )
    """)
    conn.commit()
    conn.close()

# FastAPI app
app = FastAPI(title="NeighborhoodAverageVelocityTracker")

@app.on_event("startup")
def startup():
    init_db()

# Dependency to get DB connection
def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    try:
        yield conn
    finally:
        conn.close()

# Security
security = HTTPBearer(auto_error=False)

async def get_current_user(
    credentials: Optional[HTTPAuthorizationCredentials] = Depends(security),
    db: sqlite3.Connection = Depends(get_db)
):
    if credentials is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Not authenticated")
    token = credentials.credentials
    try:
        user_id = decode_token(token)
    except JWTError:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    user = db.execute("SELECT id, email, profile_id FROM users WHERE id = ?", (user_id,)).fetchone()
    if user is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="User not found")
    return user

# Pydantic models
class RegisterRequest(BaseModel):
    email: EmailStr
    password: str

class LoginRequest(BaseModel):
    email: EmailStr
    password: str

class LocationRequest(BaseModel):
    latitude: float
    longitude: float
    timestamp: datetime

    @field_validator('latitude')
    def validate_latitude(cls, v):
        if v < -90 or v > 90:
            raise ValueError('Latitude must be between -90 and 90')
        return v

    @field_validator('longitude')
    def validate_longitude(cls, v):
        if v < -180 or v > 180:
            raise ValueError('Longitude must be between -180 and 180')
        return v

class TokenResponse(BaseModel):
    token: str
    profile_id: str

class RegisterResponse(BaseModel):
    profile_id: str
    token: str

class SummaryResponse(BaseModel):
    average_latitude: float
    average_longitude: float

# Endpoints
@app.post("/auth/register", status_code=201, response_model=RegisterResponse)
def register(req: RegisterRequest, db: sqlite3.Connection = Depends(get_db)):
    # Check if email already exists
    existing = db.execute("SELECT id FROM users WHERE email = ?", (req.email,)).fetchone()
    if existing:
        raise HTTPException(status_code=400, detail="Email already registered")
    # Hash password
    hashed = pwd_context.hash(req.password)
    # Generate unique profile_id (8 hex characters)
    profile_id = secrets.token_hex(4)
    # Insert user
    try:
        db.execute(
            "INSERT INTO users (email, hashed_password, profile_id) VALUES (?, ?, ?)",
            (req.email, hashed, profile_id)
        )
        db.commit()
    except sqlite3.IntegrityError:
        raise HTTPException(status_code=400, detail="Email already registered")
    # Retrieve user id to create token
    user = db.execute("SELECT id FROM users WHERE email = ?", (req.email,)).fetchone()
    token = create_token(user["id"])
    return {"profile_id": profile_id, "token": token}

@app.post("/auth/login", response_model=TokenResponse)
def login(req: LoginRequest, db: sqlite3.Connection = Depends(get_db)):
    user = db.execute(
        "SELECT id, hashed_password, profile_id FROM users WHERE email = ?",
        (req.email,)
    ).fetchone()
    if not user or not pwd_context.verify(req.password, user["hashed_password"]):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = create_token(user["id"])
    return {"token": token, "profile_id": user["profile_id"]}

@app.post("/locations", status_code=201)
def submit_location(
    req: LocationRequest,
    current_user=Depends(get_current_user),
    db: sqlite3.Connection = Depends(get_db)
):
    # Round coordinates to 0.01-degree grid cell
    rounded_lat = round(req.latitude * 100) / 100.0
    rounded_lon = round(req.longitude * 100) / 100.0
    # Store submission
    db.execute(
        "INSERT INTO submissions (user_id, rounded_lat, rounded_lon, timestamp) VALUES (?, ?, ?, ?)",
        (current_user["id"], rounded_lat, rounded_lon, req.timestamp.isoformat())
    )
    db.commit()
    return {}

@app.get("/summary", responses={200: {"model": SummaryResponse}, 204: {"description": "No submissions"}})
def get_summary(db: sqlite3.Connection = Depends(get_db)):
    # Get distinct grid cells that have at least one submission
    rows = db.execute("SELECT DISTINCT rounded_lat, rounded_lon FROM submissions").fetchall()
    if not rows:
        return Response(status_code=204)
    avg_lat = sum(r["rounded_lat"] for r in rows) / len(rows)
    avg_lon = sum(r["rounded_lon"] for r in rows) / len(rows)
    return {"average_latitude": avg_lat, "average_longitude": avg_lon}

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=5000)
